"use client";

interface NavbarProps {
  activeCategory: string;
  onCategoryChange: (category: string) => void;
}

const categories = [
  {
    name: "All",
    icon: "🌍",
  },
  {
    name: "Homes",
    icon: "🏠",
  },
  {
    name: "Experiences",
    icon: "🎈",
  },
  {
    name: "Services",
    icon: "🛎️",
  },
];

export default function Navbar({
  activeCategory,
  onCategoryChange,
}: NavbarProps) {
  return (
    <header className="navbar">

      {/* LOGO */}

      <div className="navbar-logo">
        <span className="navbar-logo-symbol">
          ♧
        </span>

        <span className="navbar-logo-text">
          airbnb
        </span>
      </div>

      {/* CATEGORIES */}

      <nav className="navbar-categories">

        {categories.map((category) => {

          const isActive =
            activeCategory === category.name;

          return (
            <button
              key={category.name}
              type="button"
              className={`navbar-category ${
                isActive
                  ? "active"
                  : ""
              }`}
              onClick={() =>
                onCategoryChange(
                  category.name
                )
              }
            >

              <span className="navbar-category-icon">
                {category.icon}
              </span>

              <span className="navbar-category-name">
                {category.name}
              </span>

            </button>
          );

        })}

      </nav>

      {/* RIGHT SIDE */}

      <div className="navbar-right">

        <button
          type="button"
          className="hosting-button"
        >
          Switch to hosting
        </button>

        <button
          type="button"
          className="profile-button"
          aria-label="Profile"
        >
          P
        </button>

        <button
          type="button"
          className="menu-button"
          aria-label="Menu"
        >
          ☰
        </button>

      </div>

    </header>
  );
}